const VOWELS = {
  // 3-letter vowels
  'aau': ['\u0914', '\u094C'],  // औ (extended)
  'aai': ['\u0910', '\u0948'],  // ऐ (extended)
  'aae': ['\u0910', '\u0948'],  // ऐ (alternate)
  'aao': ['\u0914', '\u094C'],  // औ (alternate)
  // 2-letter vowels
  'au': ['\u0914', '\u094C'],   // औ
  'ai': ['\u0910', '\u0948'],   // ऐ
  'aa': ['\u0906', '\u093E'],   // आ
  'ee': ['\u0908', '\u0940'],   // ई
  'ii': ['\u0908', '\u0940'],   // ई
  'oo': ['\u090A', '\u0942'],   // ऊ
  'uu': ['\u090A', '\u0942'],   // ऊ
  'ri': ['\u090B', '\u0943'],   // ऋ (as in Krishna, Rishi)
  'Ri': ['\u0960', '\u0944'],   // ॠ (long ri)
  'ru': ['\u090B', '\u0943'],   // ऋ (alternate typing)
  'ae': ['\u090F', '\u0947'],   // ए (alternate)
  'aw': ['\u0911', '\u0949'],   // ऑ/ॉ (candra o, as in टॉप, कॉफ़ी)
  // 1-letter vowels
  'a': ['\u0905', ''],          // अ (inherent)
  'i': ['\u0907', '\u093F'],    // इ
  'u': ['\u0909', '\u0941'],    // उ
  'e': ['\u090F', '\u0947'],    // ए
  'o': ['\u0913', '\u094B'],    // ओ
  // Uppercase for long vowels
  'A': ['\u0906', '\u093E'],    // आ
  'I': ['\u0908', '\u0940'],    // ई
  'U': ['\u090A', '\u0942'],    // ऊ
  'E': ['\u090F', '\u0947'],    // ए
  'O': ['\u0913', '\u094B'],    // ओ
};

const MODIFIERS = {
  '||': '\u0965', '|': '\u0964',
  'M': '\u0902', '~': '\u0901', ':': '\u0903',
};

const C_KEYS = Object.keys(CONSONANTS).sort((a, b) => b.length - a.length);
const V_KEYS = Object.keys(VOWELS).sort((a, b) => b.length - a.length);
const M_KEYS = Object.keys(MODIFIERS).sort((a, b) => b.length - a.length);

// ─────────────────────────────────────────────────────────────────────────────
//  Core: Roman → Devanagari
// ─────────────────────────────────────────────────────────────────────────────

function _toDevanagari(input) {
  let result = '', i = 0, afterConsonant = false;
  const len = input.length;

  while (i < len) {
    // Escape sequence: \x passes x through literally
    if (input[i] === '\\' && i + 1 < len) {
      result += input[i + 1]; afterConsonant = false; i += 2; continue;
    }

    // Modifiers first (||, |, M, ~, :)
    let matched = false;
    for (const mk of M_KEYS) {
      if (i + mk.length <= len && input.substr(i, mk.length) === mk) {
        result += MODIFIERS[mk]; afterConsonant = false; i += mk.length; matched = true; break;
      }
    }
    if (matched) continue;

    // Find longest matching consonant & vowel at position i
    let bestC = null, bestCLen = 0, bestV = null, bestVLen = 0;
    for (const ck of C_KEYS) {
      if (i + ck.length <= len && input.substr(i, ck.length) === ck) {
        bestC = ck; bestCLen = ck.length; break;
      }
    }
    for (const vk of V_KEYS) {
      if (i + vk.length <= len && input.substr(i, vk.length) === vk) {
        bestV = vk; bestVLen = vk.length; break;
      }
    }

    if (bestC && bestCLen >= bestVLen) {
      if (afterConsonant) result += HALANT;
      result += CONSONANTS[bestC]; afterConsonant = true; i += bestCLen;
    } else if (bestV) {
      const pair = VOWELS[bestV];
      result += afterConsonant ? pair[1] : pair[0];
      afterConsonant = false; i += bestVLen;
    } else {
      result += input[i]; afterConsonant = false; i++;
    }
  }
  return result;
}

// ─────────────────────────────────────────────────────────────────────────────
//  Script conversion: Devanagari → target script
// ─────────────────────────────────────────────────────────────────────────────

const SCRIPT_BASES = {
  devanagari: 0x0900, bengali: 0x0980, gurmukhi: 0x0A00,
  gujarati: 0x0A80, odia: 0x0B00, tamil: 0x0B80,
  telugu: 0x0C00, kannada: 0x0C80, malayalam: 0x0D00,
};

// Native digit base codepoints for each script (digit '0' starts here)
const DIGIT_BASES = {
  devanagari: 0x0966, bengali:    0x09E6, gurmukhi:  0x0A66,
  gujarati:   0x0AE6, odia:       0x0B66, tamil:     0x0BE6,
  telugu:     0x0C66, kannada:    0x0CE6, malayalam: 0x0D66,
  urdu:       0x06F0, kashmiri:   0x06F0,
};

function _convertDigits(numStr, scriptKey) {
  const base = scriptKey.includes('-') ? scriptKey.split('-')[0] : scriptKey;
  const digitBase = DIGIT_BASES[base];
  if (!digitBase) return numStr;
  return [...numStr].map(ch => String.fromCodePoint(digitBase + (ch.charCodeAt(0) - 0x30))).join('');
}

