  0x0930: '\u0631',           0x0932: '\u0644',        0x0935: '\u0648',
  0x0936: '\u0634',           0x0937: '\u0634',        0x0938: '\u0633',
  0x0939: '\u06C1',           0x093C: '',              0x094D: '',
  0x0902: '\u0646',           0x0901: '\u06BA',        0x0903: '',
  0x0964: '\u06D4',           0x0965: '\u06D4\u06D4',
