const KASHMIRI_NUKTA = {
  0x091C: '\u0632', 0x0915: '\u0642', 0x0921: '\u0691',
  0x0922: '\u0691\u06BE', 0x092B: '\u0641', 0x0917: '\u063A', 0x0916: '\u062E',
};

function _toScript(devText, scriptKey) {
  const base = scriptKey.includes('-') ? scriptKey.split('-')[0] : scriptKey;
  if (base === 'devanagari') return devText;

  // Perso-Arabic scripts (Urdu / Kashmiri)
  let _arMap = null, _arNukta = null;
  if (base === 'urdu')     { _arMap = URDU;     _arNukta = URDU_NUKTA; }
  if (base === 'kashmiri') { _arMap = KASHMIRI; _arNukta = KASHMIRI_NUKTA; }
  if (_arMap) {
    let out = '';
    for (let i = 0; i < devText.length; i++) {
      const cp = devText.codePointAt(i);
      if (i + 1 < devText.length && devText.codePointAt(i + 1) === 0x093C && _arNukta[cp]) {
        out += _arNukta[cp]; i++;
      } else if (_arMap[cp] !== undefined) {
        out += _arMap[cp];
      } else if (cp < 0x0900 || cp > 0x097F) {
        out += devText[i];
      }
    }
    return out;
  }

  // Brahmic scripts: codepoint offset remapping
  const targetBase = SCRIPT_BASES[base];
  if (!targetBase) return devText;
  const isTamil = (base === 'tamil');
  let out = '';
  for (let i = 0; i < devText.length; i++) {
    const cp = devText.codePointAt(i);
    if (cp >= 0x0900 && cp <= 0x097F) {
      if (isTamil) {
        if (cp === 0x093C) continue;
        if (TF[cp]) { out += String.fromCodePoint(TF[cp]); continue; }
      }
      out += String.fromCodePoint(targetBase + (cp - 0x0900));
    } else {
      out += devText[i];
    }
  }
  return out;
}

// ─────────────────────────────────────────────────────────────────────────────
//  Reverse: any Indic script → Devanagari
// ─────────────────────────────────────────────────────────────────────────────

// Build reverse lookup maps from existing URDU / KASHMIRI maps.
// Longer Urdu/Kashmiri strings are indexed first so the greedy matcher
// prefers them over shorter overlapping entries.
const URDU_REV = (() => {
  const rev = {};
  Object.entries(URDU)
    .filter(([, v]) => v.length > 0)
    .sort(([, a], [, b]) => b.length - a.length)
    .forEach(([devCpStr, urduStr]) => {
      if (!rev[urduStr]) rev[urduStr] = Number(devCpStr);
    });
  return rev;
})();

const KASHMIRI_REV = (() => {
  const rev = {};
  Object.entries(KASHMIRI)
    .filter(([, v]) => v.length > 0)
    .sort(([, a], [, b]) => b.length - a.length)
    .forEach(([devCpStr, kashStr]) => {
      if (!rev[kashStr]) rev[kashStr] = Number(devCpStr);
    });
  return rev;
})();

function _scriptToDevanagari(text, scriptKey) {
  const base = scriptKey.includes('-') ? scriptKey.split('-')[0] : scriptKey;
  if (base === 'devanagari') return text;

  // Perso-Arabic scripts: greedy reverse character-map lookup
  if (base === 'urdu' || base === 'kashmiri') {
    const revMap = base === 'urdu' ? URDU_REV : KASHMIRI_REV;
    const revKeys = Object.keys(revMap).sort((a, b) => b.length - a.length);
    let result = '', i = 0;
    while (i < text.length) {
      let matched = false;
      for (const key of revKeys) {
        if (text.substr(i, key.length) === key) {
          result += String.fromCodePoint(revMap[key]);
          i += key.length; matched = true; break;
        }
      }
      if (!matched) { result += text[i]; i++; }
    }
    return result;
  }

  // Brahmic scripts: reverse the codepoint-offset remapping
  const sourceBase = SCRIPT_BASES[base];
  if (!sourceBase) return text;
  let result = '';
  for (let i = 0; i < text.length; i++) {
    const cp = text.codePointAt(i);
    if (cp >= sourceBase && cp < sourceBase + 0x80) {
      result += String.fromCodePoint(0x0900 + (cp - sourceBase));
    } else {
      result += text[i];
    }
  }
  return result;
}

// ─────────────────────────────────────────────────────────────────────────────
//  Reverse: Devanagari → Roman
// ─────────────────────────────────────────────────────────────────────────────

// Devanagari consonant codepoint → phonetic Roman
const DEV_CONS = {
  0x0915: 'k',   0x0916: 'kh',  0x0917: 'g',   0x0918: 'gh',  0x0919: 'ng',
  0x091A: 'ch',  0x091B: 'chh', 0x091C: 'j',   0x091D: 'jh',  0x091E: 'ny',
  0x091F: 'T',   0x0920: 'Th',  0x0921: 'D',   0x0922: 'Dh',  0x0923: 'N',
  0x0924: 't',   0x0925: 'th',  0x0926: 'd',   0x0927: 'dh',  0x0928: 'n',
  0x092A: 'p',   0x092B: 'ph',  0x092C: 'b',   0x092D: 'bh',  0x092E: 'm',
  0x092F: 'y',   0x0930: 'r',   0x0931: 'r',   0x0932: 'l',   0x0933: 'l',
  0x0935: 'v',   0x0936: 'sh',  0x0937: 'Sh',  0x0938: 's',   0x0939: 'h',
};

// Consonant + nukta (U+093C) overrides
const DEV_NUKTA_CONS = {
  0x091C: 'z',   // ज़  → z
  0x0915: 'q',   // क़  → q
  0x0921: 'R',   // ड़  → R
  0x0922: 'Rh',  // ढ़  → Rh
  0x092B: 'f',   // फ़  → f
  0x0917: 'gh',  // ग़  → gh
  0x0916: 'kh',  // ख़  → kh
};

// Independent vowel codepoint → Roman
const DEV_IND_VOW = {
  0x0905: 'a',  0x0906: 'aa', 0x0907: 'i',  0x0908: 'ee',
  0x0909: 'u',  0x090A: 'oo', 0x090F: 'e',  0x0910: 'ai',
  0x0913: 'o',  0x0914: 'au',
};

// Dependent vowel (matra) codepoint → Roman
const DEV_MATRA = {
  0x093E: 'aa', 0x093F: 'i',  0x0940: 'ee', 0x0941: 'u',
  0x0942: 'oo', 0x0947: 'e',  0x0948: 'ai', 0x094B: 'o',
  0x094C: 'au',
};

// Modifier codepoint → Roman
const DEV_MOD_REV = {
  0x0902: 'M',   // anusvara ं
  0x0901: '~',   // chandrabindu ँ
  0x0903: ':',   // visarga ः
  0x0964: '|',   // danda ।
  0x0965: '||',  // double danda ॥
};

const HALANT_CP = 0x094D;
const NUKTA_CP  = 0x093C;

function _devanagariToRoman(text) {
  let result = '', i = 0;
  const len = text.length;

  while (i < len) {
    const cp = text.codePointAt(i);

    // ── Consonant ───────────────────────────────────────────────────────────
    if (cp in DEV_CONS) {
      let roman = DEV_CONS[cp];
      let advance = 1;

      // Nukta immediately following?
      if (i + 1 < len && text.codePointAt(i + 1) === NUKTA_CP) {
        if (cp in DEV_NUKTA_CONS) roman = DEV_NUKTA_CONS[cp];
        advance = 2;
      }

      result += roman;
      const nextI  = i + advance;
      const nextCp = nextI < len ? text.codePointAt(nextI) : -1;

      if (nextCp === HALANT_CP) {
        // Cluster consonant: suppress inherent 'a', consume halant
        i = nextI + 1;
      } else if (nextCp in DEV_MATRA) {
        // Explicit vowel sign: use it instead of inherent 'a'
        result += DEV_MATRA[nextCp];
        i = nextI + 1;
      } else {
        // Inherent vowel 'a'
        result += 'a';
        i = nextI;
      }
      continue;
    }

    // ── Independent vowel ───────────────────────────────────────────────────
    if (cp in DEV_IND_VOW) { result += DEV_IND_VOW[cp]; i++; continue; }

    // ── Orphan matra ────────────────────────────────────────────────────────
    if (cp in DEV_MATRA) { result += DEV_MATRA[cp]; i++; continue; }

    // ── Modifier ────────────────────────────────────────────────────────────
    if (cp in DEV_MOD_REV) { result += DEV_MOD_REV[cp]; i++; continue; }

    // ── Halant / Nukta (orphan — skip) ──────────────────────────────────────
    if (cp === HALANT_CP || cp === NUKTA_CP) { i++; continue; }

    // ── Pass-through (spaces, digits, Latin, punctuation) ───────────────────
    result += text[i]; i++;
  }
  return result;
}

// ─────────────────────────────────────────────────────────────────────────────
//  Variant generation (for suggestion arrays)
// ─────────────────────────────────────────────────────────────────────────────

// Helper to convert nasal clusters to anusvara form
// e.g., न्त → ंत, न्द → ंद, म्प → ंप, etc.
function _nasalToAnusvara(devText) {
  // Replace nasal + halant + consonant patterns with anusvara + consonant
  return devText
    .replace(/\u0928\u094D([\u0924-\u0928])/g, '\u0902$1')  // न् + त/थ/द/ध/न → ं + consonant
    .replace(/\u092E\u094D([\u092A-\u092E])/g, '\u0902$1')  // म् + प/फ/ब/भ/म → ं + consonant
    .replace(/\u0919\u094D([\u0915-\u0918])/g, '\u0902$1')  // ङ् + क/ख/ग/घ → ं + consonant
    .replace(/\u091E\u094D([\u091A-\u091D])/g, '\u0902$1')  // ञ् + च/छ/ज/झ → ं + consonant
    .replace(/\u0923\u094D([\u091F-\u0922])/g, '\u0902$1'); // ण् + ट/ठ/ड/ढ → ं + consonant
}

function _generateVariants(word, scriptKey) {
  if (!word || word.length < 1) return [];
  const lc = word.toLowerCase();
  const raw = [];
  const addedInputs = new Set();
  
  const add = (input) => {
    if (addedInputs.has(input)) return;
    addedInputs.add(input);
    const devText = _toDevanagari(input);
    
    // Add anusvara form FIRST (preferred in modern Hindi)
    if (scriptKey === 'devanagari' || SCRIPT_BASES[scriptKey]) {
      const anusvaraForm = _nasalToAnusvara(devText);
      if (anusvaraForm !== devText) {
        raw.push(_toScript(anusvaraForm, scriptKey));
      }
    }
    
    // Then add the explicit nasal form
    const converted = _toScript(devText, scriptKey);
    raw.push(converted);
  };

  // Add exact input first
  add(lc);

  // De-duplicate consonants (e.g., 'kk' → 'k')
  const de = lc.replace(/([bcdfghjklmnpqrstvwxyz])\1/g, '$1');
  const hasDbl = de !== lc;
  if (hasDbl) add(de);

  const bases = hasDbl ? [lc, de] : [lc];
  bases.forEach((b) => {
    let v;
    // Vowel variations - short to long and vice versa
    v = b.replace(/i(?!i|e)/g, 'ee');    if (v !== b) add(v);  // i → ī
    v = b.replace(/ee/g, 'i');           if (v !== b) add(v);  // ī → i
    v = b.replace(/u(?!u|o)/g, 'oo');    if (v !== b) add(v);  // u → ū
    v = b.replace(/oo/g, 'u');           if (v !== b) add(v);  // ū → u
    v = b.replace(/a(?![aiou])/g, 'aa'); if (v !== b) add(v);  // a → ā
    v = b.replace(/aa/g, 'a');           if (v !== b) add(v);  // ā → a
    
    // Vowel sound variations
    v = b.replace(/e(?!e|i)/g, 'ai');    if (v !== b) add(v);  // e → ai
    v = b.replace(/ai/g, 'e');           if (v !== b) add(v);  // ai → e
    v = b.replace(/o(?!o|u)/g, 'au');    if (v !== b) add(v);  // o → au
    v = b.replace(/au/g, 'o');           if (v !== b) add(v);  // au → o
    v = b.replace(/o(?!o|u|w)/g, 'aw');  if (v !== b) add(v);  // o → aw (ॉ, as in टॉप)
    v = b.replace(/aw/g, 'o');           if (v !== b) add(v);  // aw → o
    
    // ri vowel (ऋ) variations - important for Sanskrit words
    v = b.replace(/ri(?=[^i]|$)/g, 'ru'); if (v !== b) add(v); // ri → ru
    v = b.replace(/ru/g, 'ri');           if (v !== b) add(v); // ru → ri
    
    // Case-pair consonant variations (lowercase → retroflex uppercase and vice versa)
    v = b.replace(/sh/g, 'Sh');              if (v !== b) add(v);  // श → ष
    v = b.replace(/Sh/gi, 'sh');             if (v !== b) add(v);  // ष → श
    v = b.replace(/(?<![tTdDnN])n(?![tTdDhN])/g, 'N'); if (v !== b) add(v);  // न → ण
    v = b.replace(/N(?!h)/g, 'n');           if (v !== b) add(v);  // ण → न
    v = b.replace(/t(?!h)/g, 'T');           if (v !== b) add(v);  // त → ट
    v = b.replace(/T(?!h)/g, 't');           if (v !== b) add(v);  // ट → त
    v = b.replace(/d(?!h)/g, 'D');           if (v !== b) add(v);  // द → ड
    v = b.replace(/D(?!h)/g, 'd');           if (v !== b) add(v);  // ड → द
    v = b.replace(/l/g, 'L');                if (v !== b) add(v);  // ल → ळ
    v = b.replace(/r(?![aeiouAEIOUhH])/g, 'R'); if (v !== b) add(v);  // र → ड़ (before consonant)
    v = b.replace(/v/g, 'w');                if (v !== b) add(v);  // व alternate
    v = b.replace(/w/g, 'v');                if (v !== b) add(v);  // व alternate
    
    // jn/gy/gn variations for ज्ञ
    v = b.replace(/gy/g, 'jn');          if (v !== b) add(v);
    v = b.replace(/jn/g, 'gy');          if (v !== b) add(v);
    v = b.replace(/gn/g, 'gny');         if (v !== b) add(v);
    
    // ksh/x/ks variations for क्ष and क्स
    v = b.replace(/x/g, 'ksh');          if (v !== b) add(v);  // x → ksh → क्ष
    v = b.replace(/x/g, 'ks');           if (v !== b) add(v);  // x → ks → क्स
    v = b.replace(/ksh/g, 'x');          if (v !== b) add(v);
    
    // cha variations: cha→छ (chha) vs ch+a→चा (चा)
    v = b.replace(/cha/g, 'chha');      if (v !== b) add(v);  // cha → chha → छ
    v = b.replace(/cha/g, 'chaa');      if (v !== b) add(v);  // cha → chaa → चा
    
    // English loanword compound variations (retroflex + aw for words like top→टॉप, dog→डॉग)
    v = b.replace(/t(?!h)/g, 'T').replace(/o(?!o|u|w)/g, 'aw');  if (v !== b) add(v);  // top → Tawp → टॉप
    v = b.replace(/d(?!h)/g, 'D').replace(/o(?!o|u|w)/g, 'aw');  if (v !== b) add(v);  // dog → Dawg → डॉग
    v = b.replace(/o(?!o|u|w)/g, 'aw').replace(/t(?!h)/g, 'T');  if (v !== b) add(v);  // alternate order
    
    // Compound: aw + ks for words like box→बॉक्स
    v = b.replace(/o(?!o|u|w)/g, 'aw').replace(/x/g, 'ks');  if (v !== b) add(v);  // box → bawks → बॉक्स
  });

  // Add original word as fallback
  add(word);

  const seen = {};
  const unique = [];
  raw.forEach((t) => { if (!seen[t]) { seen[t] = true; unique.push(t); } });
  return unique.slice(0, 10);  // Return up to 10 suggestions
}

// ─────────────────────────────────────────────────────────────────────────────
//  Public exports
// ─────────────────────────────────────────────────────────────────────────────

/**
 * All supported script keys. Pass one of these as the `script` argument.
 * @type {string[]}
 */
export const SCRIPTS = [
  'devanagari', 'bengali', 'gurmukhi', 'gujarati', 'odia',
  'tamil', 'telugu', 'kannada', 'malayalam', 'urdu', 'kashmiri',
];

/**
 * Transliterate a full English sentence/text to the target Indic script.
 * Each word is converted independently; whitespace is preserved.
 * Uses anusvara (ं) form by default for common Hindi usage.
 *
 * @param {string} text   - English (Roman) input
 * @param {string} [script='devanagari'] - Target script key
 * @param {object} [options] - Options object
 * @param {boolean} [options.useAnusvara=true] - Use anusvara form (संत) instead of explicit nasal (सन्त)
 * @returns {string} Transliterated text
 *
 * @example
 * transliterate('namaste duniya', 'devanagari')  // → 'नमस्ते दुनिया'
 * transliterate('sant', 'devanagari')            // → 'संत'
 * transliterate('vanakkam', 'tamil')             // → 'வணக்கம்'
 */
export function transliterate(text, script = 'devanagari', { useAnusvara = true } = {}) {
  if (!text) return '';
  // Split on whitespace AND digit runs so numbers never get consumed mid-word
  return text
    .split(/(\s+|\d+)/)
    .map((token) => {
      if (!token) return token;
      if (/^\s+$/.test(token)) return token;
      if (/^\d+$/.test(token)) return _convertDigits(token, script); // convert to native digits
      const devText = _toDevanagari(token);
      const finalDev = useAnusvara ? _nasalToAnusvara(devText) : devText;
      return _toScript(finalDev, script);
    })
    .join('');
}

/**
 * Get up to 6 phonetic variant suggestions for a single English word
 * in the target script. This is the core function for building
 * IME-style suggestion UIs.
 *
 * @param {string} word   - Single English word
 * @param {string} [script='devanagari'] - Target script key
 * @returns {string[]} Array of transliteration variants (1–6 items)
 *
 * @example
 * getSuggestions('hello', 'devanagari')  // → ['हेलो', 'हेल्लो', 'हैलो', …]
 * getSuggestions('vannam', 'tamil')      // → ['வண்ணம்', …]
 */
export function getSuggestions(word, script = 'devanagari') {
  // Don't generate suggestions for empty, too-short, or number-containing words
  if (!word || word.length < 2) return [];
  if (/\d/.test(word)) return [];
  return _generateVariants(word, script);
}

/**
 * Convert English text to Devanagari only (no further script conversion).
 *
 * @param {string} text - English input
 * @returns {string} Devanagari text
 */
export function toDevanagari(text) {
  if (!text) return '';
  return text
    .split(/(\s+)/)
    .map((token) => (/^\s+$/.test(token) || !token ? token : _toDevanagari(token)))
    .join('');
}

/**
 * Convert already-transliterated Devanagari text to another Indic script.
 * Useful for cross-script conversion when you already have Devanagari.
 *
 * @param {string} devanagariText - Text in Devanagari Unicode
 * @param {string} script - Target script key
 * @returns {string} Converted text
 */
export function convertScript(devanagariText, script) {
  return _toScript(devanagariText || '', script || 'devanagari');
}

/**
 * Romanize (reverse-transliterate) Indic script text back to phonetic English.
 * Supports all 9 Brahmic scripts fully. Urdu and Kashmiri are approximate
 * because their Perso-Arabic script has many-to-one mappings.
 *
 * @param {string} text   - Text in the given Indic script
 * @param {string} [script='devanagari'] - Source script key
 * @returns {string} Phonetic Roman representation
 *
 * @example
 * romanize('नमस्ते', 'devanagari')  // → 'namaste'
 * romanize('নমস্তে', 'bengali')     // → 'namaste'
 * romanize('வணக்கம்', 'tamil')      // → 'vanakkam'
 */
export function romanize(text, script = 'devanagari') {
  if (!text) return '';
  return text
    .split(/(\s+)/)
    .map((token) => {
      if (/^\s+$/.test(token) || !token) return token;
      return _devanagariToRoman(_scriptToDevanagari(token, script));
    })
    .join('');
}
